CREATE TABLE IF NOT EXISTS wallet_accounts (address TEXT PRIMARY KEY CHECK (address ~ '^0x[0-9a-f]{40}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_nonces (address TEXT PRIMARY KEY REFERENCES wallet_accounts(address), message TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS indexed_events (chain_id BIGINT NOT NULL, block_number BIGINT NOT NULL, transaction_hash TEXT NOT NULL, log_index INTEGER NOT NULL, event_name TEXT NOT NULL, payload JSONB NOT NULL, PRIMARY KEY (chain_id, transaction_hash, log_index));
CREATE TABLE IF NOT EXISTS indexer_checkpoints (chain_id BIGINT PRIMARY KEY, block_number BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mailboxes (namehash TEXT PRIMARY KEY, owner_address TEXT NOT NULL REFERENCES wallet_accounts(address), public_key_hash TEXT NOT NULL, public_key JSONB, key_version INTEGER NOT NULL, storage_adapter TEXT NOT NULL DEFAULT 'none' CHECK (storage_adapter IN ('none','google-drive','onedrive')), storage_reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mail_messages (id UUID PRIMARY KEY, recipient_namehash TEXT NOT NULL REFERENCES mailboxes(namehash), sender_address TEXT NOT NULL REFERENCES wallet_accounts(address), nonce TEXT NOT NULL, deadline BIGINT NOT NULL, ciphertext_hash TEXT NOT NULL, ciphertext_reference TEXT NOT NULL, envelope_signature TEXT NOT NULL, delivery_state TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(sender_address, nonce));
CREATE TABLE IF NOT EXISTS mail_sender_blocks (recipient_namehash TEXT NOT NULL REFERENCES mailboxes(namehash), sender_address TEXT NOT NULL REFERENCES wallet_accounts(address), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (recipient_namehash, sender_address));
CREATE TABLE IF NOT EXISTS mail_spam_reports (id UUID PRIMARY KEY, message_id UUID NOT NULL REFERENCES mail_messages(id), reporter_address TEXT NOT NULL REFERENCES wallet_accounts(address), reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(message_id, reporter_address));
CREATE TABLE IF NOT EXISTS premium_requests (id UUID PRIMARY KEY, name TEXT NOT NULL, applicant_address TEXT NOT NULL REFERENCES wallet_accounts(address), duration_years INTEGER NOT NULL CHECK(duration_years BETWEEN 1 AND 10), reason TEXT NOT NULL, note TEXT NOT NULL, evidence_reference TEXT, status TEXT NOT NULL, quoted_registration_wei NUMERIC, quoted_renewal_wei NUMERIC, quote_expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS country_change_requests (id UUID PRIMARY KEY, address TEXT NOT NULL REFERENCES wallet_accounts(address), current_country TEXT NOT NULL, requested_country TEXT NOT NULL, reason TEXT NOT NULL, evidence_reference TEXT, status TEXT NOT NULL, decision_reason TEXT, decided_by TEXT REFERENCES wallet_accounts(address), decided_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS encrypted_evidence (id UUID PRIMARY KEY, owner_address TEXT NOT NULL REFERENCES wallet_accounts(address), purpose TEXT NOT NULL CHECK(purpose IN ('premium','country-change','brand')), filename TEXT NOT NULL, content_type TEXT NOT NULL CHECK(content_type IN ('application/pdf','image/png','image/jpeg')), byte_size INTEGER NOT NULL CHECK(byte_size > 0 AND byte_size <= 10485760), ciphertext_hash TEXT NOT NULL, ciphertext TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS marketing_consents (address TEXT PRIMARY KEY REFERENCES wallet_accounts(address), country TEXT NOT NULL, region TEXT, city TEXT, categories JSONB NOT NULL, consent_signature TEXT NOT NULL, enrolled_at TIMESTAMPTZ NOT NULL DEFAULT now(), country_locked_at TIMESTAMPTZ NOT NULL DEFAULT now(), opted_out_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS marketing_policy (singleton BOOLEAN PRIMARY KEY DEFAULT true CHECK(singleton), platform_fee_bps INTEGER NOT NULL CHECK(platform_fee_bps BETWEEN 0 AND 2000), acknowledgement_bps INTEGER NOT NULL CHECK(acknowledgement_bps >= 0), click_bps INTEGER NOT NULL CHECK(click_bps >= 0), reply_bps INTEGER NOT NULL CHECK(reply_bps >= 0), refund_days INTEGER NOT NULL CHECK(refund_days BETWEEN 1 AND 30), max_campaigns_per_day INTEGER NOT NULL CHECK(max_campaigns_per_day BETWEEN 1 AND 100), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(acknowledgement_bps + click_bps + reply_bps = 10000));
INSERT INTO marketing_policy(singleton,platform_fee_bps,acknowledgement_bps,click_bps,reply_bps,refund_days,max_campaigns_per_day) VALUES(true,1000,4000,2500,3500,7,3) ON CONFLICT(singleton) DO NOTHING;
CREATE TABLE IF NOT EXISTS geography_catalog (id UUID PRIMARY KEY, country TEXT NOT NULL, region TEXT, city TEXT, opted_in_users INTEGER, price_per_user_wei NUMERIC NOT NULL, active BOOLEAN NOT NULL DEFAULT true, UNIQUE NULLS NOT DISTINCT(country, region, city));
CREATE TABLE IF NOT EXISTS campaigns (id UUID PRIMARY KEY, chain_campaign_id TEXT UNIQUE, marketer_address TEXT NOT NULL REFERENCES wallet_accounts(address), alias TEXT NOT NULL, title TEXT NOT NULL, creative JSONB NOT NULL, categories JSONB NOT NULL, locations JSONB NOT NULL, recipient_count INTEGER NOT NULL, reward_budget_wei NUMERIC NOT NULL, platform_fee_wei NUMERIC NOT NULL, deadline TIMESTAMPTZ NOT NULL, escrow_transaction_hash TEXT, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id UUID PRIMARY KEY, actor_address TEXT, action TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
